package main

import (
	"testing"
	"time"
)

func TestProbeExpiringWithin(t *testing.T) {
	store := NewStore(60 * time.Second)
	// Query at 10080, ttl 60: a(10060) has 40s left, b(10030) has 10s,
	// c(10005) has -15s -> already expired and excluded everywhere.
	stamps := map[string]int64{"a": 10060, "b": 10030, "c": 10005}
	for id, created := range stamps {
		at := time.Unix(created, 0)
		store.now = func() time.Time { return at }
		store.Create(id, "user-"+id)
	}
	store.now = func() time.Time { return time.Unix(10080, 0) }

	got := store.SessionsExpiringWithin(30 * time.Second)
	if len(got) != 1 {
		t.Fatalf("got %d, want 1 (only b within 30s)", len(got))
	}
	if got[0].ID != "b" {
		t.Fatalf("got %s, want b", got[0].ID)
	}

	// Wider window catches b too, ordered by remaining (a before b).
	got = store.SessionsExpiringWithin(50 * time.Second)
	if len(got) != 2 || got[0].ID != "b" || got[1].ID != "a" {
		t.Fatalf("wide window = [%s %s], want [b a]", got[0].ID, got[1].ID)
	}

	// d <= 0: empty.
	if got := store.SessionsExpiringWithin(0); len(got) != 0 {
		t.Fatalf("d=0 returned %d", len(got))
	}
	if got := store.SessionsExpiringWithin(-time.Second); len(got) != 0 {
		t.Fatalf("negative d returned %d", len(got))
	}

	// No mutation: the query never writes. c is still in the map (Len
	// counts raw entries, not live ones).
	if store.Len() != 3 {
		t.Fatalf("store mutated: %d", store.Len())
	}
}
EOF
go test -count=1 . ; rc=$? ; rm -f probe_expiring_test.go ; exit $rc

